        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Das Glück begreifen, daß der Boden, auf dem du stehst, nicht größer sein kann, als die zwei Füße ihn bedecken.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Das Gute ist in gewissem Sinne trostlos.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Der Geist wird erst frei, wenn er aufhört, Halt zu sein.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Die Demut gibt jedem, auch dem einsam Verzweifelnden, das stärkste Verhältnis zum Mitmenschen und zwar sofort, allerdings nur bei völliger und dauernder Demut.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Du bist die Aufgabe. Kein Schüler weit und breit.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Du kannst dich zurückhalten von den Leiden der Welt, das ist dir freigestellt und entspricht deiner Natur, aber vielleicht ist gerade dieses Zurückhalten das einzige Leid, das du vermeiden könntest.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Ein erstes Zeichen beginnender Erkenntnis ist der Wunsch zu sterben.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Früher begriff ich nicht, warum ich auf meine Frage keine Antwort bekam, heute begreife ich nicht, wie ich glauben konnte, fragen zu können. Aber ich glaubte ja gar nicht, ich fragte nur.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Im Kampf zwischen dir und der Welt sekundiere der Welt.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Prüfe dich an der Menschheit. Den Zweifelnden macht sie zweifeln, den Glaubenden glauben.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Verstecke sind unzählige, Rettung nur eine, aber Möglichkeiten der Rettung wieder so viele wie Verstecke. Es gibt ein Ziel, aber keinen Weg; was wir Weg nennen, ist Zögern.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Von einem gewissen Punkt an gibt es keine Rückkehr mehr. Dieser Punkt ist zu erreichen.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Wahrheit ist unteilbar, kann sich also selbst nicht erkennen; wer sie erkennen will, muß Lüge sein.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Wenn das, was im Paradies zerstört worden sein soll, zerstörbar war, dann war es nicht entscheidend; war es aber unzerstörbar, dann leben wir in einem falschen Glauben.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Das Gericht will nichts von dir. Es nimmt dich auf, wenn du kommst, und es entlässt dich, wenn du gehst.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Das Urteil kommt nicht mit einemmal, das Verfahren geht allmählich ins Urteil über.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Die Logik ist zwar unerschütterlich, aber einem Menschen, der leben will, widersteht sie nicht.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Die Lüge wird zur Weltordnung gemacht.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Die Schrift ist unveränderlich und die Meinungen sind oft nur ein Ausdruck der Verzweiflung darüber.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Hier konnte niemand sonst Einlaß erhalten, denn dieser Eingang war nur für dich bestimmt. Ich gehe jetzt und schließe ihn.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Jemand mußte Josef K. verleumdet haben, denn ohne daß er etwas Böses getan hätte, wurde er eines Morgens verhaftet.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Richtiges Auffassen einer Sache und Mißverstehn der gleichen Sache schließen einander nicht vollständig aus.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "„Wie ein Hund!“ sagte er, es war, als sollte die Scham ihn überleben.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Wie kann denn ein Mensch überhaupt schuldig sein. Wir sind hier doch alle Menschen, einer wie der andere.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Das Zögern vor der Geburt. Gibt es eine Seelenwanderung, dann bin ich noch nicht auf der untersten Stufe. Mein Leben ist das Zögern vor der Geburt.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Deutschland hat Rußland den Krieg erklärt. – Nachmittag Schwimmschule.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Die Argumentation im allgemeinen: Ich bin an Felice verloren.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Die Eltern, die Dankbarkeit von ihren Kindern erwarten (es gibt sogar solche, die sie fordern), sind wie Wucherer, sie riskieren gern das Kapital, wenn sie nur die Zinsen bekommen.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Ein Mensch, der kein Tagebuch hat, ist einem Tagebuch gegenüber in einer falschen Position.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Ein unglücklicher Mensch, der kein Kind haben soll, ist in sein Unglück schrecklich eingeschlossen.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Es gibt Möglichkeiten für mich, gewiß, aber unter welchem Stein liegen sie?", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Goethe hält durch die Macht seiner Werke die Entwicklung der deutschen Sprache wahrscheinlich zurück.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Ich bin unpünktlich, weil ich die Schmerzen des Wartens nicht fühle. Ich warte wie ein Rind.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Ich habe keine Zeit, Briefe doppelt zu schreiben.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Vor dem Heiraten hütet er [E.K.] sich, trotzdem er schon vierunddreißig Jahre alt ist, denn die Amerikanerinnen heiraten oft nur, um sich scheiden zu lassen, was für sie sehr einfach, für den Mann aber sehr teuer ist.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Was bist du? Elend bin ich. Zwei Brettchen gegen die Schläfen geschraubt habe ich.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Was ich geleistet habe, ist nur ein Erfolg des Alleinseins.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Verbringe nicht die Zeit mit dem Suchen des Hindernisses, vielleicht ist keines da.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Zweifellos ist in mir die Gier nach Büchern. Nicht eigentlich sie zu besitzen oder zu lesen, als vielmehr sie zu sehn, mich in der Auslage eines Buchhändlers von ihrem Bestand zu überzeugen.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Manches Buch wirkt wie ein Schlüssel zu fremden Sälen des eigenen Schlosses.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Ich glaube, man sollte überhaupt nur solche Bücher lesen, die einen beißen und stechen. Wenn das Buch, das wir lesen, uns nicht mit einem Faustschlag auf den Schädel weckt, wozu lesen wir dann das Buch?", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Ein Buch muß die Axt sein für das gefrorene Meer in uns.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Liebe ist, daß Du mir das Messer bist, mit dem ich in mir wühle.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Manchmal scheint es mir, Gehirn und Lunge hätten sich ohne mein Wissen verständigt. 'So geht es nicht weiter' hat das Gehirn gesagt und nach fünf Jahren hat sich die Lunge bereit erklärt, zu helfen.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Der Gedanke, einmal in seiner Größe gefaßt, kann nicht mehr verschwinden; solange es Menschen gibt, wird auch der starke Wunsch da sein, den Turm zu Ende zu bauen.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Der Grundsatz, nach dem ich entscheide, ist: Die Schuld ist immer zweifellos.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Das Schönste an meinem Bau ist aber seine Stille. Freilich, sie ist trügerisch. Plötzlich einmal kann sie unterbrochen werden und alles ist zu Ende. Vorläufig aber ist sie noch da.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "In diesem Augenblick ging über die Brücke ein geradezu unendlicher Verkehr.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Je länger man vor der Tür zögert, desto fremder wird man.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Wie könnten Narren müde werden!", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Das Geschriebene ist ja nur Schlacke des Erlebnisses.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Die Jugend ist glücklich, weil sie die Fähigkeit hat, Schönheit zu sehen. Jeder, der die Fähigkeit behält, Schönheit zu sehen, wird niemals alt.", Author = "Franz Kafka" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Franz_Kafka", Text = "Nein. Dichtung ist Verdichtung, eine Essenz. Literatur ist dagegen Auflösung, ein Genußmittel, das das unbewußte Leben erleichtert, ein Narkotikum. [...] Dichtung ist das gerade Gegenteil. Dichtung erweckt.", Author = "Franz Kafka" },
        };
